/* ============================================================
   05b — ЗВУК УЛЬТЫ МЕЧА РОКОЧУЩЕГО РЫЦАРЯ
   Пользовательский mp3 ВСТРОЕН в билд (base64) и проигрывается через тот же
   WebAudio-граф, что и остальные эффекты (с учётом громкости SFX/общей).
   ============================================================ */
const KNIGHT_SLASH_MP3 = 'data:audio/mpeg;base64,';

/* Проигрывание встроенного mp3 через общий sfx-шину. Декодируем один раз. */
Audio3D_SFX._knightBuf = null;
Audio3D_SFX._knightLoading = false;
Audio3D_SFX._knightDecode = function () {
  if (this._knightBuf || this._knightLoading || !this.ctx) return;
  this._knightLoading = true;
  const self = this;
  try {
    const b = atob(KNIGHT_SLASH_MP3.split(',')[1]);
    const n = b.length;
    const u8 = new Uint8Array(n);
    for (let i = 0; i < n; i++) u8[i] = b.charCodeAt(i);
    const done = (buf) => { self._knightBuf = buf; self._knightLoading = false; };
    const fail = () => { self._knightLoading = false; };
    const p = this.ctx.decodeAudioData(u8.buffer, done, fail);
    if (p && p.then) p.then(done).catch(fail);
  } catch (e) { this._knightLoading = false; }
};

/* Ульта: проигрываем встроенный рёв рыцаря на полной громкости (не позиционный —
   это кинематографический эффект у экрана). */
Audio3D_SFX.knightSlash = function () {
  if (!this.ctx || this.muted) return;
  this._knightDecode();
  const self = this;
  const fire = () => {
    if (!self._knightBuf) return false;
    const src = self.ctx.createBufferSource();
    src.buffer = self._knightBuf;
    const g = self.ctx.createGain();
    g.gain.value = 0.95;
    src.connect(g); g.connect(self.sfx);
    src.start();
    return true;
  };
  if (!fire()) {
    // буфер ещё декодируется — подождём и сыграем один раз
    let tries = 0;
    const iv = setInterval(() => {
      if (fire() || ++tries > 40) clearInterval(iv);
    }, 50);
  }
};